#!/usr/bin/env bash
set -Eeuo pipefail
umask 077
[[ $EUID == 0 && $(uname -s) == Linux && $(uname -m) == x86_64 ]] || { echo 'Run as root on Linux amd64'; exit 1; }
command -v python3 >/dev/null || { echo 'Python 3 is required to open the installation panel'; exit 1; }
if [[ ${ULTRAFULL_FORCE_UPDATE:-0} != 1 && -x /usr/local/bin/ultrafull && -f /opt/ultrafull/manifest.json ]] && python3 - <<'VERIFY_LOCAL'
import hashlib,json,pathlib,sys
root=pathlib.Path('/opt/ultrafull')
try:
 m=json.loads((root/'manifest.json').read_text());files={p:s for p,s in m['installer_files'].items() if p.startswith('app/')}
 assert 'app/ultrafull.py' in files
 for name,digest in files.items():
  p=root/name;assert p.resolve().is_relative_to(root) and not p.is_symlink() and hashlib.sha256(p.read_bytes()).hexdigest()==digest
except (OSError,ValueError,KeyError,AssertionError):sys.exit(1)
VERIFY_LOCAL
then
 exec /usr/local/bin/ultrafull "$@"
fi
work=$(mktemp -d /var/tmp/ultrafull-commercial.XXXXXXXX)
chmod 700 "$work"
trap 'rm -rf -- "$work"' EXIT
cat > "$work/bootstrap.py" <<'ULTRAFULL_PYTHON'
import base64,json,pathlib,sys,os
root=pathlib.Path(__file__).resolve().parent
bundle=root/'bootstrap.zip';bundle.write_bytes(base64.b64decode(''))
sys.path.insert(0,str(bundle))
(root/'edition.json').write_text(json.dumps({'product': 'ULTRAFULL', 'version': '0.2.7', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9', 'token_bootstrap_sha256': '29e83ad1dcc63f2cacb259f0124793ae3d83f7c9b12202ff89ade3d629f63307'}))
from ufcommercial import common
common.APP=root
from ufcommercial.installer_ui import run
try:
 run({'product': 'ULTRAFULL', 'version': '0.2.7', 'authority': 'https://ultraradar.ultranec.pro:9448', 'verify_key': 'f73170b1de1eb7c0b04e6abae68a5587f1f6d6fdbd76747c56ae5c9fb8072ce9', 'token_bootstrap_sha256': '29e83ad1dcc63f2cacb259f0124793ae3d83f7c9b12202ff89ade3d629f63307'},folder=root)
except KeyboardInterrupt:
 pass
except Exception:
 print('ULTRAFULL could not open the installer. Use an interactive SSH terminal with TERM=xterm-256color.')
 raise SystemExit(1) from None

ULTRAFULL_PYTHON
python3 "$work/bootstrap.py"
